// -----------------------------------------------------------------------------------------------------------
// palette

struct Color { double r, g, b; };

inline constexpr Color fromHex(uint32_t rgb) noexcept
{
    return Color{ ((rgb >> 16) & 0xFF) / 255.0, ((rgb >> 8) & 0xFF) / 255.0, (rgb & 0xFF) / 255.0 };
}

static constexpr Color kBg        { 0.059, 0.035, 0.031 }; // #0f0908
static constexpr Color kTextMain  { 0.94, 0.90, 0.855 };   // #f0e6da
static constexpr Color kTextDim   { 0.60, 0.55, 0.51 };
static constexpr Color kAccent    { 0.910, 0.576, 0.353 }; // #e8935a
static constexpr Color kKnobBody  { 0.00, 0.00, 0.00 };
static constexpr Color kKnobRing  { 0.94, 0.90, 0.855 };
static constexpr Color kBtnBg     { 0.114, 0.110, 0.235 };

// -----------------------------------------------------------------------------------------------------------
// layout model

struct Knob
{
    uint32_t param;
    float cx, cy, radius;
    const char* label;
    Color accent;
};

struct Button { float x, y, w, h; const char* label; Color accent; };

struct PresetBarLayout
{
    Button prev, next, save, del;
    float nameX, nameY, nameW, nameH;
    Color accent;
};

// the semi-modular patch matrix: mirrors PhellipePlugin.cpp's Src/Dest enums
// exactly (both ultimately mirror the source-major patch_<src>_<dest> block
// in Params.hpp) - keep all three in sync.
enum PatchSrc { PatchSrcDrift = 0, PatchSrcAmpEnv, PatchSrcFilterEnv, PatchSrcLfo, PatchSrcModWheel, PatchSrcPitchBend,
                PatchSrcVelocity, PatchSrcAftertouch, kPatchNumSources };
enum PatchDest { PatchDestPitch = 0, PatchDestCutoff, PatchDestWave, PatchDestDelayTime, PatchDestChorusRate, PatchDestLfoRate, PatchDestAge,
                 PatchDestOscBFree, PatchDestOscCFree, PatchDestResonance, PatchDestDrive, PatchDestChorusDepth, PatchDestSpaceSize,
                 PatchDestDelayMix, PatchDestNoise, kPatchNumDests };

static constexpr float kJackRadius = 7.0f;

struct Jack { float cx = 0.0f, cy = 0.0f; int index = -1; };

struct Layout
{
    float width, height;
    std::vector<Knob> knobs;
    PresetBarLayout presetBar;
    std::array<Jack, kPatchNumSources> sourceJacks; // indexed by PatchSrc
    std::array<Jack, kPatchNumDests> destJacks;      // indexed by PatchDest
};

// -----------------------------------------------------------------------------------------------------------
// layout builder

inline void addKnobRow(std::vector<Knob>& knobs, float rowCenterX, float rowW, float rowY, float radius,
                        Color accent, const std::vector<std::pair<uint32_t, const char*>>& items)
{
    const float rowX = rowCenterX - rowW / 2.0f;
    const float slot = rowW / (float)items.size();
    size_t i = 0;
    for (const auto& item : items)
    {
        const float cx = rowX + slot * ((float)i + 0.5f);
        knobs.push_back({ item.first, cx, rowY, radius, item.second, accent });
        ++i;
    }
}

struct CellPolygonBounds { float x, y, w, h, cx, cy; };

inline CellPolygonBounds boundsOf(const VoronoiCellGeo& cell) noexcept
{
    float minX = cell.polygon[0].first, maxX = minX;
    float minY = cell.polygon[0].second, maxY = minY;
    for (const auto& p : cell.polygon)
    {
        minX = std::min(minX, p.first);  maxX = std::max(maxX, p.first);
        minY = std::min(minY, p.second); maxY = std::max(maxY, p.second);
    }
    return { minX, minY, maxX - minX, maxY - minY, (minX + maxX) * 0.5f, (minY + maxY) * 0.5f };
}

// one row of knobs within a cell - most cells have exactly one (subLabel
// nullptr); CORE has three (the shared unison row, then one per additional
// tunable oscillator, each with its own small sub-label).
struct KnobRowSpec
{
    const char* subLabel; // nullptr = no sub-label drawn above this row
    std::vector<std::pair<uint32_t, const char*>> knobs;
};

// per-functional-cell content: title/subtitle/knob row(s), anchored at the
// cell's polygon-bbox center plus a hand-tuned (dx,dy) nudge - checked
// visually against this exact geometry (see tools/gen_voronoi.py) so it's
// known to clear each polygon's edges.
struct CellContent
{
    const char* tag;
    const char* title;
    const char* subtitle;
    float titleSize;
    float dx, dy;
    float knobRadius;
    float rowWidth;
    float rowSpacing; // vertical distance between successive knob rows
    float rowDxStep = 0.0f; // extra rightward shift per row index - the
                             // polygon's left edge can encroach further at
                             // lower rows (e.g. CORE's hexagon narrows
                             // toward its bottom-left corner), so later rows
                             // need to sit further right to stay clear of it
    std::vector<KnobRowSpec> rows;
};

